package com.mobileapp.api.crypto;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class TokenService {

    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private final byte[] masterKey;
    private final FeatureFlagService featureFlags;
    private final Map<String, Long> decryptionTimings = new ConcurrentHashMap<>();

    public TokenService(byte[] masterKey, FeatureFlagService featureFlags) {
        this.masterKey = masterKey.clone();
        this.featureFlags = featureFlags;
    }

    public static class TokenResult {
        public final boolean valid;
        public final String errorCode;
        public final byte[] payload;

        private TokenResult(boolean valid, String errorCode, byte[] payload) {
            this.valid = valid;
            this.errorCode = errorCode;
            this.payload = payload;
        }

        public static TokenResult success(byte[] payload) {
            return new TokenResult(true, null, payload);
        }

        public static TokenResult failure(String errorCode) {
            return new TokenResult(false, errorCode, null);
        }
    }

    public TokenResult validateToken(String encryptedToken, String clientId) {
        if (encryptedToken == null || encryptedToken.isEmpty()) {
            return TokenResult.failure("EMPTY_TOKEN");
        }

        byte[] tokenBytes;
        try {
            tokenBytes = Base64.getDecoder().decode(encryptedToken);
        } catch (IllegalArgumentException e) {
            return TokenResult.failure("INVALID_ENCODING");
        }

        if (tokenBytes.length < 32 || tokenBytes.length % 16 != 0) {
            return TokenResult.failure("INVALID_LENGTH");
        }

        byte[] iv = new byte[16];
        byte[] ciphertext = new byte[tokenBytes.length - 16];
        System.arraycopy(tokenBytes, 0, iv, 0, 16);
        System.arraycopy(tokenBytes, 16, ciphertext, 0, ciphertext.length);

        return performDecryption(iv, ciphertext, clientId);
    }

    private TokenResult performDecryption(byte[] iv, byte[] ciphertext, String clientId) {
        try {
            SecretKeySpec keySpec = new SecretKeySpec(masterKey, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(iv);

            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
            byte[] plaintext = cipher.doFinal(ciphertext);

            if (!verifyTokenStructure(plaintext, clientId)) {
                return TokenResult.failure("INVALID_STRUCTURE");
            }

            return TokenResult.success(plaintext);
        } catch (javax.crypto.BadPaddingException e) {
            return handleDecryptionError(e, clientId);
        } catch (Exception e) {
            return handleDecryptionError(e, clientId);
        }
    }

    private TokenResult handleDecryptionError(Exception e, String clientId) {
        if (featureFlags.isEnabled("detailed_error_logging", clientId)) {
            logDetailedError(e, clientId);
        }

        if (featureFlags.isEnabled("granular_error_codes", clientId)) {
            return mapToGranularError(e);
        }

        return TokenResult.failure("DECRYPTION_FAILED");
    }

    private TokenResult mapToGranularError(Exception e) {
        return TokenResult.failure("DECRYPTION_FAILED");
    }

    private void logDetailedError(Exception e, String clientId) {
        System.err.println("[TokenService] Decryption failed for client " + sanitizeForLog(clientId)
                + ": " + e.getClass().getSimpleName() + " - " + sanitizeForLog(e.getMessage()));
    }

    private String sanitizeForLog(String input) {
        if (input == null) {
            return "null";
        }
        return input.replaceAll("[\\r\\n]", "_");
    }

    private boolean verifyTokenStructure(byte[] plaintext, String clientId) {
        if (plaintext.length < 8) return false;
        long timestamp = 0;
        for (int i = 0; i < 8; i++) {
            timestamp = (timestamp << 8) | (plaintext[i] & 0xFF);
        }
        long now = System.currentTimeMillis();
        return Math.abs(now - timestamp) < 300000;
    }
}

class FeatureFlagService {
    private final Map<String, Boolean> globalFlags;
    private final Map<String, Map<String, Boolean>> clientOverrides;

    public FeatureFlagService() {
        this.globalFlags = new ConcurrentHashMap<>();
        this.clientOverrides = new ConcurrentHashMap<>();
        initializeDefaults();
    }

    private void initializeDefaults() {
        globalFlags.put("detailed_error_logging", false);
        globalFlags.put("granular_error_codes", false);
        globalFlags.put("rate_limiting_v2", true);
        globalFlags.put("token_rotation", true);
    }

    public boolean isEnabled(String flagName, String clientId) {
        Map<String, Boolean> overrides = clientOverrides.get(clientId);
        if (overrides != null && overrides.containsKey(flagName)) {
            return overrides.get(flagName);
        }
        return globalFlags.getOrDefault(flagName, false);
    }

    public void setClientOverride(String clientId, String flagName, boolean value) {
        clientOverrides.computeIfAbsent(clientId, k -> new ConcurrentHashMap<>())
                .put(flagName, value);
    }

    public void setGlobalFlag(String flagName, boolean value) {
        globalFlags.put(flagName, value);
    }
}
